/**
 * Contains functions for communicating with a remote server and handling messages received via Tauri channels.
 */
import { log_error } from "../services/Logger";
import { invoke } from "@tauri-apps/api/core";
import { listen, UnlistenFn, emit } from "@tauri-apps/api/event";
import { SocketInterface, OnMessageCallback } from "./SocketInterface";

/**
 * A singleton class that acts as an Adaptor for Tauri channels that
 * communicates with the backend.
 */
export class TauriSocketAdaptor implements SocketInterface {
  /** The single instance of TauriSocketAdaptor */
  private static _instance?: TauriSocketAdaptor;
  /** The flag indicating whether the channel connection is open */
  private open: boolean = false;
  /** The callback that executes when a message is received from the server */
  private readonly onMessage?: OnMessageCallback = undefined;
  /** The channel name for this connection */
  private channelName: string = "remote-message";
  /** The unsubscribe function for the event listener */
  private unlisten?: UnlistenFn;

  /**
   * Constructs a new instance of TauriSocketAdaptor.
   * @param channelName - Optional custom channel name.
   * @param onMessage - A callback that executes when a message is received from the server.
   */
  constructor(channelName: string | undefined, onMessage: OnMessageCallback) {
    // Ensure only one instance exists.
    if (TauriSocketAdaptor._instance) {
      return TauriSocketAdaptor._instance;
    }
    TauriSocketAdaptor._instance = this;

    // Initialize properties.
    this.onMessage = onMessage;
    if (channelName) {
      this.channelName = channelName;
    }
    
    this.setupChannel();
  }

  static CloseAll = () => {
    if (TauriSocketAdaptor._instance) {
      TauriSocketAdaptor._instance.close();
      TauriSocketAdaptor._instance = undefined;
    }
  }

  /**
   * Sets up the Tauri channel and listeners
   */
  async setupChannel() {
    try {
      // Connect to the channel
      await invoke('channel_connect', { channelName: this.channelName });
      
      // Setup event listener
      this.unlisten = await listen(this.channelName, (event) => {
        this.onReceive(event);
      });
      
      this.open = true;
      
      // Send initial state request
      this.send({ SendLastState: null });
      
      console.log(`Connected to channel: ${this.channelName}`);
    } catch (error) {
      console.error(`Error setting up channel: ${error}`);
      this.retryReconnect();
    }
  }

  retryReconnect = () => {
  }

  checkConnection = () => {
    if (!this.isReady()) {
      console.log("Connection is not ready, attempting to reconnect...");
      this.retryReconnect();
    } else {
      this.send({ Ping: Date.now() });
    }
  }

  /**
   * Closes the channel connection.
   */
  close = (code?: number, reason?: string) => {
    if (this.unlisten) {
      this.unlisten();
      this.unlisten = undefined;
    }
    this.open = false;
  }

  /**
   * Sends a string to the remote server.
   * @param message - The message to send.
   */
  send_string = (message: string) => {
    if (this.open) {
      try {
        const data = JSON.parse(message);
        this.send(data);
      } catch (e) {
        log_error(`Failed to parse message: ${e}`);
      }
    }
  }

  /**
   * Sends a message to the remote server.
   * @param message - The message to send.
   */
  send = <T,>(message: T) => {
    if (this.open) {
      try {
        // Emit the message to the backend via the channel
        emit(this.channelName + "-backend", message);
      } catch (error) {
        console.error(`Error sending message: ${error}`);
      }
    }
  }

  /**
   * Processes a message received from the server.
   * @param event - The event containing the message.
   */
  onReceive = (event: any) => {
    if (this.open && this.onMessage) {
      try {
        // The payload should already be parsed by Tauri
        const message = event.payload;
        this.onMessage(message);
      } catch (error) {
        log_error(`Error processing received message: ${error}`);
      }
    }
  }

  /**
   * Returns true if the channel is open and ready for communication.
   * @return - A boolean indicating if the channel is open.
   */
  isReady = (): boolean => {
    return this.open;
  }
} 